export const envelope = [63, 28, 63];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = Math.floor(W / 2);
  const cz = Math.floor(D / 2);

  // 3D Grid Buffer for precise geometry and deterministic output
  const grid = new Array(W * H * D).fill(null);

  function idx(x, y, z) {
    return (y * D + z) * W + x;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[idx(x, y, z)] = block;
    }
  }

  // Pre-sample terrain heights around structure footprint
  const groundH = {};
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      if (dx * dx + dz * dz <= 20 * 20) {
        const h = api.heightAt(x, z);
        groundH[`${x},${z}`] = Math.max(-2, Math.min(3, Math.round(h)));
      }
    }
  }

  function getGround(x, z) {
    const k = `${x},${z}`;
    return groundH[k] !== undefined ? groundH[k] : 0;
  }

  // =========================================================================
  // 1. GROUND SCORCH & CROP CIRCLE ENERGY MATRIX (y = 0..3)
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);

      if (r <= 16.5) {
        const gh = getGround(x, z);
        const angle = Math.atan2(dz, dx);

        let surfBlock = null;
        const spoke = Math.abs(Math.sin(angle * 4));
        const isRune = spoke < 0.13 && r >= 3.0 && r <= 15.0;

        if (r <= 3.8) {
          surfBlock = "minecraft:crying_obsidian";
        } else if (Math.abs(r - 5.5) <= 0.6) {
          surfBlock = "minecraft:sea_lantern";
        } else if (Math.abs(r - 8.5) <= 0.6) {
          surfBlock = "minecraft:prismarine_bricks";
        } else if (Math.abs(r - 12.0) <= 0.6) {
          surfBlock = isRune ? "minecraft:sea_lantern" : "minecraft:crying_obsidian";
        } else if (Math.abs(r - 15.0) <= 0.6) {
          surfBlock = "minecraft:dark_prismarine";
        } else if (isRune) {
          surfBlock = Math.floor(r) % 2 === 0 ? "minecraft:sea_lantern" : "minecraft:prismarine_bricks";
        } else if (r <= 15.5) {
          surfBlock = Math.floor(r + Math.sin(angle * 6)) % 2 === 0
            ? "minecraft:polished_blackstone"
            : "minecraft:deepslate_tiles";
        }

        if (surfBlock) {
          const minY = Math.min(0, gh);
          const maxY = Math.max(0, gh);
          for (let y = minY; y <= maxY; y++) {
            set(x, y, z, y === maxY ? surfBlock : "minecraft:deepslate_tiles");
          }
        }
      }
    }
  }

  // =========================================================================
  // 2. CENTRAL TRACTOR BEAM & GRAV-STABILIZER PYLONS (y = 0..14)
  // =========================================================================
  // Core Abduction Energy Vortex
  for (let y = 0; y <= 13; y++) {
    for (let dx = -5; dx <= 5; dx++) {
      for (let dz = -5; dz <= 5; dz++) {
        const x = cx + dx;
        const z = cz + dz;
        const gh = getGround(x, z);
        if (y < gh) continue;

        const r = Math.sqrt(dx * dx + dz * dz);
        const angle = Math.atan2(dz, dx);

        if (r <= 1.5) {
          if (y === 0 || y === 1) {
            set(x, y, z, "minecraft:beacon");
          } else if (y % 2 === 0) {
            set(x, y, z, "minecraft:sea_lantern");
          } else {
            set(x, y, z, "minecraft:cyan_concrete");
          }
        } else if (r <= 3.2) {
          const spiral = Math.sin(angle * 3 + y * 0.65);
          if (spiral > 0.25) {
            set(x, y, z, "minecraft:cyan_stained_glass");
          } else if (spiral > -0.35) {
            set(x, y, z, "minecraft:light_blue_stained_glass");
          } else {
            set(x, y, z, "minecraft:sea_lantern");
          }
        } else if (r <= 4.2) {
          if (y % 3 === 0) {
            set(x, y, z, "minecraft:cyan_stained_glass");
          }
        }
      }
    }
  }

  // 4 Bio-mechanical Grav-Pylons rooting the ship into the terrain
  const pylonAngles = [Math.PI * 0.25, Math.PI * 0.75, Math.PI * 1.25, Math.PI * 1.75];
  for (let y = 0; y <= 14; y++) {
    const pylonRadius = 5.0 + 6.5 * Math.pow(y / 14.0, 1.3);
    for (const pa of pylonAngles) {
      const px = cx + Math.round(pylonRadius * Math.cos(pa));
      const pz = cz + Math.round(pylonRadius * Math.sin(pa));

      for (let ox = -1; ox <= 1; ox++) {
        for (let oz = -1; oz <= 1; oz++) {
          if (ox * ox + oz * oz <= 2) {
            const x = px + ox;
            const z = pz + oz;
            const gh = getGround(x, z);
            if (y >= gh) {
              if (ox === 0 && oz === 0) {
                set(x, y, z, y % 3 === 0 ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone_bricks");
              } else {
                set(x, y, z, "minecraft:deepslate_tiles");
              }
            }
          }
        }
      }
    }
  }

  // =========================================================================
  // 3. MOTHERSHIP DREADNOUGHT HULL GEOMETRY (y = 10..27)
  // =========================================================================
  function getHullInfo(u, v) {
    if (v < -27 || v > 26) return null;
    const absU = Math.abs(u);
    let isFuselage = false;
    let isWing = false;
    let isEngine = false;

    // Fuselage width profile
    let wf = 0;
    if (v < -20) {
      wf = 2.5 + (v + 27) * 0.85;
    } else if (v <= 0) {
      const t = (v + 20) / 20.0;
      wf = 8.45 + 6.55 * (1.0 - (1.0 - t) * (1.0 - t));
    } else if (v <= 16) {
      wf = 15.0 - 1.5 * (v / 16.0);
    } else {
      wf = 13.5 - 2.5 * ((v - 16) / 10.0);
    }

    if (absU <= wf) {
      isFuselage = true;
    }

    // Swept pincer wings
    if (v >= -14 && v <= 22) {
      let ww = 0;
      if (v <= 6) {
        const t = (v + 14) / 20.0;
        ww = 12.0 + 15.5 * Math.sin(t * Math.PI * 0.5);
      } else {
        const t = (v - 6) / 16.0;
        ww = 27.5 - 12.0 * Math.pow(t, 1.2);
      }

      if (absU <= ww) {
        if (v < 10) {
          isWing = true;
        } else {
          const wnotch = 11.0 + 3.0 * ((v - 10) / 12.0);
          if (absU >= wnotch || absU <= wf) {
            isWing = true;
          }
        }
      }
    }

    // Engine housings
    if (v >= 12 && v <= 26) {
      if ((absU >= 5.5 && absU <= 12.5) || (absU <= 3.5 && v <= 24)) {
        isEngine = true;
      }
    }

    if (!isFuselage && !isWing && !isEngine) return null;

    let maxW = wf;
    if (v >= -14 && v <= 22) {
      const ww = v <= 6
        ? 12.0 + 15.5 * Math.sin(((v + 14) / 20.0) * Math.PI * 0.5)
        : 27.5 - 12.0 * Math.pow((v - 6) / 16.0, 1.2);
      maxW = Math.max(maxW, ww);
    }
    const normDist = Math.min(1.0, absU / (maxW + 0.01));

    return { isFuselage, isWing, isEngine, normDist, absU, v };
  }

  // Render hull blocks
  for (let z = 0; z < D; z++) {
    const v = z - cz;
    for (let x = 0; x < W; x++) {
      const u = x - cx;
      const hInfo = getHullInfo(u, v);
      if (!hInfo) continue;

      const { isFuselage, isWing, isEngine, normDist, absU } = hInfo;
      const Y_mid = 15.5 + 0.8 * (v / 26.0);

      // Half-thickness calculation
      let H_fuse = 0;
      if (v < -20) {
        H_fuse = 1.2 + 1.8 * ((v + 27) / 7.0);
      } else if (v <= 0) {
        H_fuse = 3.0 + 3.0 * ((v + 20) / 20.0);
      } else if (v <= 16) {
        H_fuse = 6.0 - 0.5 * (v / 16.0);
      } else {
        H_fuse = 5.5 - 1.5 * ((v - 16) / 10.0);
      }

      const H_wing = 1.2 + 2.3 * Math.pow(Math.max(0, 1.0 - normDist), 1.1);
      let H_eff = 0;

      if (isWing && !isFuselage) {
        H_eff = H_wing;
      } else {
        H_eff = H_fuse * (1.0 - 0.65 * Math.pow(normDist, 1.4));
        if (isWing) {
          H_eff = Math.max(H_eff, H_wing);
        }
      }

      if (isEngine) {
        H_eff = Math.max(H_eff, 3.6);
      }

      let y_bot = Math.floor(Y_mid - H_eff);
      let y_top = Math.ceil(Y_mid + H_eff);

      // Bridge superstructure dome on top
      if (absU <= 6.0 && v >= -7 && v <= 7) {
        const r_br = Math.sqrt(Math.pow(u / 6.0, 2) + Math.pow(v / 7.0, 2));
        if (r_br <= 1.0) {
          y_top = Math.max(y_top, Math.ceil(Y_mid + 4.5 + 3.5 * (1.0 - r_br * r_br)));
        }
      }

      // Dorsal spine fin
      if (absU <= 1.2 && v >= -20 && v <= 16) {
        const spineAdd = 1.8 * (1.0 - Math.abs(v) / 24.0);
        y_top = Math.max(y_top, Math.ceil(Y_mid + H_eff + spineAdd));
      }

      // Core belly reactor chamber on underside
      if (u * u + v * v <= 49) {
        const r_core = Math.sqrt(u * u + v * v) / 7.0;
        y_bot = Math.min(y_bot, Math.floor(Y_mid - 6.0 + 1.8 * r_core));
      }

      y_bot = Math.max(10, Math.min(23, y_bot));
      y_top = Math.max(y_bot, Math.min(26, y_top));

      // Layer placement
      for (let y = y_bot; y <= y_top; y++) {
        const isBottomLayer = y === y_bot;
        const isTopLayer = y === y_top;

        // Underside energy conduits
        const isDiagonalConduit = Math.abs(absU - Math.abs(v)) <= 0.8 && v >= -15 && v <= 15;
        const isSpineConduit = absU === 0;
        const isTransverseConduit = Math.abs(v) % 4 === 0 && absU <= 16;

        if (isBottomLayer) {
          if (isDiagonalConduit || (isSpineConduit && v >= -15 && v <= 10)) {
            set(x, y, z, "minecraft:sea_lantern");
          } else if (isTransverseConduit) {
            set(x, y, z, "minecraft:prismarine_bricks");
          } else if ((v + 100) % 3 === 0) {
            set(x, y, z, "minecraft:polished_blackstone");
          } else {
            set(x, y, z, "minecraft:deepslate_tiles");
          }
        } else if (isTopLayer) {
          if (absU === 0 && v >= -22 && v <= 18) {
            set(x, y, z, v % 3 === 0 ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone_bricks");
          } else if (absU === 3 || absU === 7) {
            set(x, y, z, "minecraft:chiseled_deepslate");
          } else if ((absU + v + 100) % 5 === 0) {
            set(x, y, z, "minecraft:polished_blackstone_bricks");
          } else {
            set(x, y, z, "minecraft:deepslate_tiles");
          }
        } else {
          if (isDiagonalConduit && y <= Y_mid) {
            set(x, y, z, "minecraft:cyan_concrete");
          } else {
            set(x, y, z, "minecraft:polished_deepslate");
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. ENGINE THRUSTER PLUMES & NOZZLE COWLINGS (z = 49..57)
  // =========================================================================
  const engineXCenters = [cx - 9, cx + 9, cx];
  for (const ex of engineXCenters) {
    const isCenter = ex === cx;
    const rad = isCenter ? 2.5 : 3.2;

    for (let z = cz + 18; z <= cz + 26; z++) {
      for (let x = ex - 4; x <= ex + 4; x++) {
        for (let y = 13; y <= 21; y++) {
          const dX = x - ex;
          const dY = y - (16.5 + (isCenter ? 0.5 : 0));
          const dist2D = Math.sqrt(dX * dX + dY * dY);

          if (dist2D <= rad) {
            if (z >= cz + 24) {
              if (dist2D <= 1.2) {
                set(x, y, z, "minecraft:sea_lantern");
              } else if (dist2D <= 2.2) {
                set(x, y, z, "minecraft:cyan_stained_glass");
              } else {
                set(x, y, z, "minecraft:light_blue_stained_glass");
              }
            } else if (z === cz + 23) {
              if (dist2D >= rad - 1.0) {
                set(x, y, z, "minecraft:chiseled_deepslate");
              } else {
                set(x, y, z, "minecraft:beacon");
              }
            }
          }
        }
      }
    }
  }

  // =========================================================================
  // 5. COMMAND BRIDGE INTERIOR HOLLOW & SENSOR MAST
  // =========================================================================
  // Hollow interior volume for compiler furnishing
  for (let x = 28; x <= 34; x++) {
    for (let y = 17; y <= 20; y++) {
      for (let z = 26; z <= 36; z++) {
        set(x, y, z, null);
      }
    }
  }

  // Solid bridge floor at y = 16
  for (let x = 27; x <= 35; x++) {
    for (let z = 25; z <= 37; z++) {
      const isRing = Math.abs(x - cx) <= 2 && Math.abs(z - (cz - 1)) <= 2;
      set(x, 16, z, isRing ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone_bricks");
    }
  }

  // Forward observation viewport facing North
  for (let x = 29; x <= 33; x++) {
    for (let y = 18; y <= 19; y++) {
      set(x, y, 25, "minecraft:cyan_stained_glass");
    }
  }

  // Recessed ceiling lighting strip
  for (let z = 27; z <= 35; z++) {
    set(cx, 21, z, "minecraft:sea_lantern");
  }

  // Dorsal sensor array & communication spires
  set(cx, 26, cz, "minecraft:polished_deepslate_wall");
  set(cx, 27, cz, "minecraft:lightning_rod[facing=up]");
  set(cx - 5, 24, cz - 2, "minecraft:end_rod[facing=up]");
  set(cx + 5, 24, cz - 2, "minecraft:end_rod[facing=up]");

  // =========================================================================
  // 6. FLUSH TO OUTPUT STREAM
  // =========================================================================
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid[idx(x, y, z)];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Alien Mothership Dreadnought",
    seatY: 0,
    anchors: {
      front: [cx, 16, 0],
      beam: [cx, 0, cz],
      bridge: [cx, 17, cz]
    },
    interiors: [
      {
        min: [28, 17, 26],
        max: [34, 20, 36],
        kind: "bridge"
      }
    ]
  };
}

