export const envelope = [24, 14, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  const key = (x, y, z) => `${x},${y},${z}`;
  const setVoxel = (x, y, z, block) => {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set(key(x, y, z), block);
    }
  };
  const getVoxel = (x, y, z) => grid.get(key(x, y, z)) || null;

  // Theme ground roles with robust fallbacks
  const gBank = api.theme.ground?.bank || "minecraft:dirt";
  const gScree = api.theme.ground?.scree || "minecraft:coarse_dirt";
  const gPave = api.theme.ground?.pavement || "minecraft:cobblestone";
  const sPrimary = api.theme.stone?.primary || "minecraft:stone";

  // Sci-fi & alien materials
  const HULL_ARMOR = "minecraft:polished_blackstone";
  const HULL_PLATE = "minecraft:iron_block";
  const HULL_TRIM = "minecraft:dark_prismarine";
  const HULL_ALLOY = "minecraft:purpur_block";
  const HULL_RIB = "minecraft:purpur_pillar[axis=y]";
  const CONDUIT_CORE = "minecraft:crying_obsidian";
  const CONDUIT_GLOW = "minecraft:sea_lantern";
  const CONDUIT_PIPE = "minecraft:oxidized_copper";
  const CONDUIT_CRYSTAL = "minecraft:amethyst_block";
  const DOME_GLASS = "minecraft:tinted_glass";

  // Seat plane is at y = 3
  const seatY = 3;

  // --- PHASE 1: Crater & Impact Trench ---
  const craterCenterX = 11.5;
  const craterCenterZ = 12.0;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - craterCenterX;
      const dz = z - craterCenterZ;
      const distCenter = Math.sqrt(dx * dx + dz * dz);

      // Trench leading from crash trajectory (North-South slide)
      const clampedZ = Math.max(3, Math.min(13, z));
      const distTrench = Math.sqrt((x - craterCenterX) * (x - craterCenterX) + (z - clampedZ) * (z - clampedZ));
      const distEff = Math.min(distCenter, distTrench * 1.15);

      // Calculate terrain height profile around crater
      let surfaceY = seatY;
      if (distEff < 3.8) {
        // Impact gouge pit
        surfaceY = 1.0 + (distEff / 3.8) * 0.8;
      } else if (distEff < 7.5) {
        // Crater bowl
        surfaceY = 1.8 + ((distEff - 3.8) / 3.7) * 1.2;
      } else if (distEff < 9.8) {
        // Raised ejecta rim
        const rimPhase = ((distEff - 7.5) / 2.3) * Math.PI;
        surfaceY = 3.0 + Math.sin(rimPhase) * 1.4;
      } else {
        // Outer undisturbed ground
        surfaceY = seatY;
      }

      // Small deterministic ripple for organic earth mound
      surfaceY += Math.sin(x * 1.3 + z * 0.7) * 0.35 + Math.cos(z * 1.7 - x * 0.5) * 0.25;
      const groundH = Math.max(1, Math.min(6, Math.round(surfaceY)));

      // Solid ground from base y = 0 up to crater surface
      for (let y = 0; y <= groundH; y++) {
        if (y === groundH) {
          // Surface layer
          if (distEff < 3.2) {
            // Scorched core
            const r = (x * 7 + z * 13) % 10;
            if (r < 4) setVoxel(x, y, z, "minecraft:magma_block");
            else if (r < 7) setVoxel(x, y, z, "minecraft:crying_obsidian");
            else setVoxel(x, y, z, "minecraft:blackstone");
          } else if (distEff < 6.5) {
            // Blast zone
            const r = (x * 11 + z * 17) % 10;
            if (r < 4) setVoxel(x, y, z, "minecraft:basalt");
            else if (r < 7) setVoxel(x, y, z, "minecraft:blackstone");
            else setVoxel(x, y, z, gScree);
          } else if (distEff < 9.8) {
            // Rim rubble
            const r = (x * 5 + z * 9) % 10;
            if (r < 4) setVoxel(x, y, z, gScree);
            else if (r < 7) setVoxel(x, y, z, gPave);
            else setVoxel(x, y, z, gBank);
          } else {
            setVoxel(x, y, z, gBank);
          }
        } else if (y >= groundH - 1) {
          // Sub-surface scorched rock/dirt
          if (distEff < 5.0) {
            setVoxel(x, y, z, "minecraft:basalt");
          } else {
            setVoxel(x, y, z, gBank);
          }
        } else {
          // Deep foundation
          setVoxel(x, y, z, sPrimary);
        }
      }
    }
  }

  // --- PHASE 2: Saucer Geometry ---
  // The saucer is tilted: nose plowed down toward North (-Z), starboard roll
  const saucerCenter = [11.5, 5.0, 11.5];
  const pitch = -0.38; // ~22 degrees pitch down into ground
  const roll = 0.22;   // ~12.5 degrees bank roll

  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const cosR = Math.cos(roll);
  const sinR = Math.sin(roll);

  // Orthonormal basis vectors for the saucer's local frame
  const right = [cosR, sinR, 0];
  const up = [-sinR * cosP, cosR * cosP, sinP];
  const fwd = [sinR * sinP, -cosR * sinP, cosP];

  const saucerRadius = 7.8;

  for (let x = 1; x < W - 1; x++) {
    for (let y = 1; y < H - 1; y++) {
      for (let z = 1; z < D - 1; z++) {
        const dx = x - saucerCenter[0];
        const dy = y - saucerCenter[1];
        const dz = z - saucerCenter[2];

        // Transform world point into local craft coordinates
        const lx = dx * right[0] + dy * right[1] + dz * right[2];
        const ly = dx * up[0] + dy * up[1] + dz * up[2];
        const lz = dx * fwd[0] + dy * fwd[1] + dz * fwd[2];

        const r = Math.sqrt(lx * lx + lz * lz);
        if (r > saucerRadius + 0.5) continue;

        // Disc vertical profile thickness
        const hullThick = 1.65 * (1.0 - Math.pow(Math.min(1.0, r / saucerRadius), 1.7));

        // Upper bridge dome
        let domeTop = 0;
        if (r < 3.4) {
          domeTop = 0.6 + 2.1 * Math.sqrt(Math.max(0, 1.0 - (r * r) / (3.4 * 3.4)));
        }

        // Lower thruster core bulge
        let coreBot = 0;
        if (r < 3.0) {
          coreBot = -0.5 - 1.3 * Math.sqrt(Math.max(0, 1.0 - (r * r) / (3.0 * 3.0)));
        }

        const topBound = Math.max(hullThick, domeTop);
        const botBound = Math.min(-hullThick, coreBot);

        // Check if point is inside saucer volume
        if (ly < botBound - 0.2 || ly > topBound + 0.2) continue;

        // Polar angle in saucer plane
        const phi = Math.atan2(lz, lx);

        // --- CRASH BREACH & TORN HULL ---
        // Rear-starboard catastrophic breach where alien conduits are exposed
        const inBreachSector = phi > 0.5 && phi < 2.2 && r > 2.6;
        const breachNoise = Math.sin(phi * 4.0 + r * 1.8) + Math.cos(ly * 2.5);
        const isTornAway = inBreachSector && breachNoise > -0.2 && ly > -0.6;

        if (isTornAway) {
          // Exposed alien guts / conduits
          if (r < 4.2 && Math.abs(ly) < 0.8) {
            const conduitType = (Math.abs(Math.round(lx * 3 + lz * 5))) % 4;
            if (conduitType === 0) setVoxel(x, y, z, CONDUIT_CORE);
            else if (conduitType === 1) setVoxel(x, y, z, CONDUIT_GLOW);
            else if (conduitType === 2) setVoxel(x, y, z, CONDUIT_PIPE);
            else setVoxel(x, y, z, CONDUIT_CRYSTAL);
          } else if (Math.sin(phi * 6.0) > 0.4) {
            // Exposed structural ribs
            setVoxel(x, y, z, HULL_RIB);
          }
          // Other voxels in breach remain empty air/gash
          continue;
        }

        // --- INTACT HULL & COCKPIT ---
        if (r < 3.4 && ly > 0.9) {
          // Upper canopy / bridge
          if (ly > topBound - 0.5 || r > 2.8) {
            // Dome frame vs glass
            const spoke = Math.abs(Math.sin(phi * 2.0));
            if (spoke < 0.25 || ly > 2.2) {
              setVoxel(x, y, z, HULL_ALLOY);
            } else {
              setVoxel(x, y, z, DOME_GLASS);
            }
          } else {
            // Interior bridge core
            if (r < 1.4 && ly < 1.6) {
              setVoxel(x, y, z, CONDUIT_CORE);
            } else {
              setVoxel(x, y, z, CONDUIT_GLOW);
            }
          }
        } else if (r >= saucerRadius - 1.1) {
          // Outer perimeter rim
          const rimSpoke = Math.sin(phi * 4.0);
          if (rimSpoke > 0.75) {
            setVoxel(x, y, z, CONDUIT_GLOW);
          } else if (rimSpoke < -0.75) {
            setVoxel(x, y, z, CONDUIT_CORE);
          } else {
            setVoxel(x, y, z, HULL_ARMOR);
          }
        } else if (ly <= -0.6 && r < 3.0) {
          // Lower reactor core
          if (r < 1.5) {
            setVoxel(x, y, z, CONDUIT_GLOW);
          } else {
            setVoxel(x, y, z, CONDUIT_CORE);
          }
        } else {
          // Main hull plating layers
          if (r >= 5.0 && r < 6.4) {
            setVoxel(x, y, z, HULL_TRIM);
          } else if (r >= 3.4 && r < 4.6) {
            setVoxel(x, y, z, HULL_ALLOY);
          } else {
            const spoke = Math.abs(Math.sin(phi * 3.0));
            if (spoke < 0.15) {
              setVoxel(x, y, z, CONDUIT_PIPE);
            } else {
              setVoxel(x, y, z, (Math.abs(x + z) % 2 === 0) ? HULL_PLATE : HULL_ARMOR);
            }
          }
        }
      }
    }
  }

  // --- PHASE 3: Embedded Hull Debris, Fire & Smoke ---
  // Smoking impact emitters & sparks in the crater
  const smokeSpots = [
    [10, 2, 8],
    [15, 3, 14],
    [8, 3, 13],
    [13, 2, 6]
  ];

  for (const [sx, sy, sz] of smokeSpots) {
    if (getVoxel(sx, sy, sz)) {
      setVoxel(sx, sy, sz, "minecraft:blackstone");
      setVoxel(sx, sy + 1, sz, "minecraft:soul_campfire[lit=true,facing=north]");
      // Ensure clearance above campfire for smoke pillar
      setVoxel(sx, sy + 2, sz, "minecraft:air");
      setVoxel(sx, sy + 3, sz, "minecraft:air");
    }
  }

  // Scattered broken hull shards embedded in crater rim
  const debris = [
    [5, 4, 15, HULL_ALLOY],
    [5, 5, 16, HULL_ARMOR],
    [18, 4, 7, HULL_TRIM],
    [19, 5, 6, CONDUIT_CORE],
    [17, 4, 17, HULL_PLATE],
    [18, 5, 17, CONDUIT_PIPE],
    [7, 3, 5, HULL_ARMOR],
    [6, 4, 5, HULL_ALLOY]
  ];

  for (const [dx, dy, dz, block] of debris) {
    setVoxel(dx, dy, dz, block);
  }

  // Protruding lightning rod conduits from the breach
  const rods = [
    [15, 6, 16, "minecraft:lightning_rod[facing=east]"],
    [16, 5, 15, "minecraft:lightning_rod[facing=up]"],
    [14, 7, 17, "minecraft:end_rod[facing=up]"],
    [17, 7, 13, "minecraft:lightning_rod[facing=north]"]
  ];

  for (const [rx, ry, rz, rod] of rods) {
    if (!getVoxel(rx, ry, rz)) {
      setVoxel(rx, ry, rz, rod);
    }
  }

  // --- PHASE 4: Emit All Blocks Deterministically ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = getVoxel(x, y, z);
        if (b && b !== "minecraft:air") {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Crashed Alien Saucer",
    seatY: seatY,
    anchors: {
      front: [12, 3, 0],
      impact: [12, 2, 7],
      breach: [16, 6, 15],
      reactor: [12, 5, 12]
    }
  };
}

